// Tranche verticale minimale : modèle -> service -> API -> vue
@RestController
class TaskController {
  @PostMapping("/tasks")
  ResponseEntity<Task> create(@RequestBody TaskRequest req) {
    Task task = taskService.create(req.title());
    return ResponseEntity.status(201).body(task);
  }
}
